INSERT INTO t_article (id,title,author,tone,audio,video,time_text,tag,content) VALUES ('g3','降压药怎么吃更安全','心内科 · 王志强','photo',TRUE,FALSE,'06:20','高血压','降压药怎么吃更安全。本文由心内科 · 王志强提供，围绕高血压给出可执行的日常建议：规律监测、按时用药、控制饮食中的盐与糖、保持每周 150 分钟中等强度运动。出现明显不适时请及时就医。');
INSERT INTO t_article (id,title,author,tone,audio,video,time_text,tag,content) VALUES ('g4','血压管理','慢病管理团队','wave',TRUE,FALSE,'03:20','高血压','血压管理。本文由慢病管理团队提供，围绕高血压给出可执行的日常建议：规律监测、按时用药、控制饮食中的盐与糖、保持每周 150 分钟中等强度运动。出现明显不适时请及时就医。');
INSERT INTO t_article (id,title,author,tone,audio,video,time_text,tag,content) VALUES ('g5','运动前先测血压','康复科 · 张敏','video',TRUE,TRUE,'04:10','运动','运动前先测血压。本文由康复科 · 张敏提供，围绕运动给出可执行的日常建议：规律监测、按时用药、控制饮食中的盐与糖、保持每周 150 分钟中等强度运动。出现明显不适时请及时就医。');
INSERT INTO t_article (id,title,author,tone,audio,video,time_text,tag,content) VALUES ('g6','情绪与血压管理','心理科 · 周敏','wave',TRUE,FALSE,'05:00','心理','情绪与血压管理。本文由心理科 · 周敏提供，围绕心理给出可执行的日常建议：规律监测、按时用药、控制饮食中的盐与糖、保持每周 150 分钟中等强度运动。出现明显不适时请及时就医。');
INSERT INTO t_article (id,title,author,tone,audio,video,time_text,tag,content) VALUES ('g7','低血糖的识别与急救','内分泌科 · 刘芳','photo',FALSE,TRUE,'07:30','急救','低血糖的识别与急救。本文由内分泌科 · 刘芳提供，围绕急救给出可执行的日常建议：规律监测、按时用药、控制饮食中的盐与糖、保持每周 150 分钟中等强度运动。出现明显不适时请及时就医。');
